def product_bound(v,d,p,scale=0):
    w=e(-(F(1,2)-d)*v)
    mass=6*w+F(400,H)
    powers=4*w+10*e(-(F(2,3)-d)*v)
    z=p+((1+1/v)*mass+powers)/v**scale
    return z/(1-z*v**(scale-1)*e(-d*v))

